# -*- coding: utf-8 -*-
# Nelin 11, proof tasks 0–19. Wrong/garbled keys fixed: 10.2(2), 5.3.10, 6.5.4. Unchanged: 4, 7, 9, 10, 14, 16, 17.
P = {'G11_TB_10_2_10_2_1': {'k': '$x^{2} + 3 - 4\\sqrt{x} = (x - 1)^{2} + 2(\\sqrt{x} - 1)^{2} \\ge 0$ (раскрыв скобки, получаем $x^{2} - 2x + 1 + 2x - 4\\sqrt{x} + 2$), поэтому $x^{2} + 3 \\ge 4\\sqrt{x}$.', 'd': [('Возведём в квадрат: $(x^{2} + 3)^{2} \\ge 16x$; при $x = 1$ получаем $16 \\ge 16$, значит, неравенство верно при всех $x \\ge 1$.', 'Проверка в одной точке не доказывает неравенства для всех $x \\ge 1$.'), ('По неравенству о средних $x^{2} + 3 \\ge 2x\\sqrt{3}$, а $2x\\sqrt{3} \\ge 4\\sqrt{x}$ при $x \\ge 1$, поэтому неравенство верно.', '$2x\\sqrt{3} \\ge 4\\sqrt{x}$ равносильно $x \\ge \\left(\\dfrac{2}{\\sqrt{3}}\\right)^{2} = \\dfrac{4}{3}$, т. е. неверно при $1 \\le x < \\dfrac{4}{3}$.'), ('$x^{2} + 3 - 4\\sqrt{x} = (x - 2)^{2} + 4x - 4\\sqrt{x} - 1$, и при $x \\ge 1$ все слагаемые неотрицательны.', 'Слагаемое $-1$ отрицательно, поэтому вывод «все слагаемые неотрицательны» неверен; нужна запись $(x - 1)^{2} + 2(\\sqrt{x} - 1)^{2}$.')]}, 'G11_TB_10_2_10_2_2': {'k': "Для $f(x) = \\sin x - x + \\dfrac{2x^{2}}{\\pi}$ имеем $f''(x) = -\\sin x + \\dfrac{4}{\\pi} > 0$ (так как $\\dfrac{4}{\\pi} > 1 \\ge \\sin x$), поэтому $f'$ возрастает, и $f'(x) > f'(0) = 0$ при $x > 0$; значит, $f$ возрастает и $f(x) > f(0) = 0$ на $\\left(0; \\dfrac{\\pi}{2}\\right)$.", 'd': [('$f(0) = 0$ и $f\\left(\\dfrac{\\pi}{2}\\right) = 1 > 0$, поэтому $f(x) > 0$ на всём интервале $\\left(0; \\dfrac{\\pi}{2}\\right)$.', 'Знаки на концах ничего не говорят о знаке внутри интервала; нужно исследовать монотонность.'), ('При $x > 0$ имеем $\\sin x \\ge x$, поэтому $\\sin x \\ge x > x - \\dfrac{2x^{2}}{\\pi}$.', 'При $x > 0$ верно обратное: $\\sin x < x$.'), ("$f'(x) = \\cos x - 1 + \\dfrac{4x}{\\pi}$ и $f'(0) = 0$, поэтому $x = 0$ — точка минимума, и $f(x) > f(0) = 0$ при $x > 0$.", "Из $f'(0) = 0$ не следует, что $0$ — точка минимума; нужно показать, что $f' > 0$ на всём интервале.")]}, 'G11_TB_10_2_10_2_3': {'k': "$f(x) = \\sin x - \\dfrac{2}{\\pi}x$ равна нулю при $x = 0$ и $x = \\dfrac{\\pi}{2}$, а $f''(x) = -\\sin x < 0$ на $\\left(0; \\dfrac{\\pi}{2}\\right)$, т. е. график выпуклый вверх и лежит выше хорды — отрезка оси $Ox$ между нулями, поэтому $f(x) > 0$.", 'd': [('Разложение $\\sin x = x - \\dfrac{x^{3}}{6} + \\ldots$ показывает, что вблизи нуля $\\sin x > \\dfrac{2}{\\pi}x$, а по непрерывности это сохраняется на всём интервале.', 'Непрерывность не гарантирует сохранения знака на всём интервале; вдали от нуля нужно отдельное обоснование.'), ('При $x = \\dfrac{\\pi}{6}$, $\\dfrac{\\pi}{4}$, $\\dfrac{\\pi}{3}$ неравенство выполняется, поэтому оно верно при всех $0 < x < \\dfrac{\\pi}{2}$.', 'Проверка в нескольких точках не доказывает неравенства для всех $x$.'), ("$f'(x) = \\cos x - \\dfrac{2}{\\pi} > 0$ на $\\left(0; \\dfrac{\\pi}{2}\\right)$, поэтому $f$ возрастает и $f(x) > f(0) = 0$.", "$f'(x) < 0$ при $\\cos x < \\dfrac{2}{\\pi}$, т. е. вблизи $\\dfrac{\\pi}{2}$; функция сначала возрастает, потом убывает до $f\\left(\\dfrac{\\pi}{2}\\right) = 0$.")]}, 'G11_TB_1_4_3': {'k': 'Для $z = a + bi$, $w = c + di$ имеем $\\overline{z} = a - bi$, и свойства проверяются вычислением: например, $\\overline{zw} = (ac - bd) - (ad + bc)i = (a - bi)(c - di) = \\overline{z} \\cdot \\overline{w}$, $\\overline{z + w} = \\overline{z} + \\overline{w}$, $z + \\overline{z} = 2a$, $z\\overline{z} = a^{2} + b^{2} = |z|^{2}$.', 'd': 'KEEP'}, 'G11_TB_22_1_16': {'k': 'Вероятности равны: каждый набор из $6$ номеров — один из $C_{49}^{6}$ равновозможных исходов, и его вероятность $\\dfrac{1}{C_{49}^{6}}$ не зависит от того, какие номера в нём.', 'd': [('Набор Даниила более вероятен, потому что маленькие номера выпадают чаще.', 'Все номера равновозможны; вероятность любого набора равна $\\dfrac{1}{C_{49}^{6}}$.'), ('Набор Наташи более вероятен, потому что «разбросанные» номера встречаются чаще, чем подряд идущие.', 'Каждый конкретный набор — один равновозможный исход; «разбросанность» на вероятность не влияет.'), ('Сравнить вероятности невозможно, так как результат лотереи случаен.', 'Случайность не мешает сравнить: все наборы равновероятны.')]}, 'G11_TB_22_1_17': {'k': 'Нет, шансы не увеличатся: тиражи независимы, и в каждом тираже любая комбинация имеет одну и ту же вероятность $\\dfrac{1}{C_{49}^{6}}$ независимо от прошлых результатов.', 'd': 'KEEP'}, 'G11_TB_22_2_3_6': {'d': [('$A \\cdot \\varnothing = A$, так как умножение на невозможное событие не меняет событие.', 'Произведение событий происходит, когда происходят оба; невозможное событие не происходит никогда.'), ('$A \\cdot \\varnothing = \\Omega$, так как невозможное событие дополняет $A$ до достоверного.', 'Дополнение до достоверного даёт сумма $A + \\overline{A}$, а не произведение с $\\varnothing$.'), ('$A \\cdot \\varnothing = A + \\varnothing$, так как для событий произведение и сумма совпадают.', 'Сумма происходит, если происходит хотя бы одно событие, произведение — если оба; это разные операции.')]}, 'G11_TB_2_6': {'k': 'Для $z_{1} = r_{1}(\\cos\\varphi_{1} + i\\sin\\varphi_{1})$, $z_{2} = r_{2}(\\cos\\varphi_{2} + i\\sin\\varphi_{2})$ по формулам косинуса и синуса суммы $z_{1}z_{2} = r_{1}r_{2}(\\cos(\\varphi_{1} + \\varphi_{2}) + i\\sin(\\varphi_{1} + \\varphi_{2}))$ — модули перемножаются, аргументы складываются; деление — действие, обратное умножению ($\\dfrac{r_{1}}{r_{2}}$, $\\varphi_{1} - \\varphi_{2}$), а степень — многократное умножение: $z^{n} = r^{n}(\\cos n\\varphi + i\\sin n\\varphi)$.', 'd': 'KEEP'}, 'G11_TB_5_3_10': {'k': "Пусть угол при вершине $2\\alpha$, $0 < \\alpha < \\dfrac{\\pi}{2}$; тогда боковые стороны $2R\\cos\\alpha$ и $S = \\dfrac{1}{2}(2R\\cos\\alpha)^{2}\\sin 2\\alpha = 4R^{2}\\sin\\alpha\\cos^{3}\\alpha$. Производная $(\\sin\\alpha\\cos^{3}\\alpha)' = \\cos^{2}\\alpha(\\cos^{2}\\alpha - 3\\sin^{2}\\alpha)$ меняет знак с «+» на «−» при $\\operatorname{tg}\\alpha = \\dfrac{1}{\\sqrt{3}}$, т. е. $2\\alpha = \\dfrac{\\pi}{3}$ — треугольник равносторонний.", 'd': [('Боковые стороны $2R\\sin\\alpha$, поэтому $S = 4R^{2}\\sin^{3}\\alpha\\cos\\alpha$, максимум при $\\alpha = \\dfrac{\\pi}{3}$, т. е. угол при вершине $120^{\\circ}$ — наибольшая площадь у тупоугольного треугольника.', 'Боковая сторона лежит против угла при основании $\\dfrac{\\pi}{2} - \\alpha$, поэтому она равна $2R\\cos\\alpha$.'), ('Наибольшую площадь имеет прямоугольный равнобедренный треугольник, так как у него катеты перпендикулярны и площадь $\\dfrac{1}{2}ab$ максимальна.', 'Площадь прямоугольного равнобедренного треугольника равна $R^{2}$, а равностороннего — $\\dfrac{3\\sqrt{3}}{4}R^{2} \\approx 1{,}3R^{2}$, что больше.'), ('Площадь вписанного треугольника не зависит от угла при вершине, так как все вершины лежат на одной окружности.', 'Площадь зависит от угла: при $\\alpha \\to 0$ или $\\alpha \\to \\dfrac{\\pi}{2}$ она стремится к нулю.')]}, 'G11_TB_6_1_2': {'d': [('При подстановке $x = 3$ получается $\\dfrac{0}{0}$, а это $0$, поэтому предел равен $0$.', '$\\dfrac{0}{0}$ — неопределённость, а не число; при $x \\ne 3$ дробь равна $x + 3$.'), ('Для любого $\\varepsilon > 0$ возьмём $\\delta = \\varepsilon$: при $|x - 3| < \\delta$ имеем $\\left|\\dfrac{x^{2} - 9}{x - 3} - 6\\right| = |x + 3| < \\varepsilon$.', '$\\dfrac{x^{2} - 9}{x - 3} - 6 = x + 3 - 6 = x - 3$, а не $x + 3$.'), ('При $x \\ne 3$ дробь равна $x + 3$, поэтому предел равен $3 \\cdot 3 = 9$.', '$x + 3$ при $x \\to 3$ стремится к $3 + 3 = 6$.')]}, 'G11_TB_6_1_4': {'d': [('Предел не существует, так как функция $f(x) = x$ не является постоянной.', 'Предел существует и у непостоянных функций: при $\\delta = \\varepsilon$ из $|x - a| < \\delta$ следует $|x - a| < \\varepsilon$.'), ('Для любого $\\varepsilon > 0$ возьмём $\\delta = 2\\varepsilon$: при $|x - a| < \\delta$ имеем $|x - a| < \\varepsilon$.', 'Из $|x - a| < 2\\varepsilon$ не следует $|x - a| < \\varepsilon$; нужно $\\delta \\le \\varepsilon$.'), ('$\\lim\\limits_{x \\to a} x = x$, так как функция равна своему аргументу.', 'Предел — число, не зависящее от $x$; здесь оно равно $a$.')]}, 'G11_TB_6_3_6_3_9': {'d': [('Если приращение функции стремится к нулю, то функция постоянна вблизи точки $x_{0}$.', '$\\Delta f \\to 0$ означает лишь малость приращений (непрерывность), а не их равенство нулю.'), ('Предел приращения функции при $\\Delta x \\to 0$ всегда равен бесконечности, так как делить на нуль нельзя.', 'Здесь нет деления: $\\Delta f = f(x_{0} + \\Delta x) - f(x_{0})$; для непрерывной функции $\\Delta f \\to 0$.'), ('Для непрерывной функции предел приращения функции равен приращению аргумента.', '$\\lim\\limits_{\\Delta x \\to 0}\\Delta f = 0$; приращения функции и аргумента в общем случае не равны.')]}, 'G11_TB_6_5_4': {'k': '$\\dfrac{\\operatorname{tg} x}{x} = \\dfrac{\\sin x}{x} \\cdot \\dfrac{1}{\\cos x}$, а $\\lim\\limits_{x \\to 0}\\dfrac{\\sin x}{x} = 1$ и $\\lim\\limits_{x \\to 0}\\cos x = 1$, поэтому предел равен $1 \\cdot \\dfrac{1}{1} = 1$.', 'd': [('При $x = 0$ числитель и знаменатель равны нулю, поэтому предел равен $\\dfrac{0}{0} = 0$.', '$\\dfrac{0}{0}$ — неопределённость; её раскрывают через $\\lim\\limits_{x \\to 0}\\dfrac{\\sin x}{x} = 1$.'), ('$\\dfrac{\\operatorname{tg} x}{x} = \\dfrac{\\sin x}{x} \\cdot \\cos x$, поэтому предел равен $1 \\cdot 1 = 1$.', '$\\operatorname{tg} x = \\dfrac{\\sin x}{\\cos x}$, поэтому множитель — $\\dfrac{1}{\\cos x}$; ответ совпал случайно.'), ('$\\lim\\limits_{x \\to 0}\\dfrac{\\operatorname{tg} x}{x} = \\dfrac{\\lim \\operatorname{tg} x}{\\lim x} = \\dfrac{0}{0} = 1$.', 'Теорема о пределе частного применима только при ненулевом пределе знаменателя.')]}}
